import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const _=JSON.parse('{"title":"期中测试 | 这些Redis源码知识，你都掌握了吗？","description":"","frontmatter":{},"headers":[{"level":3,"title":"选择题","slug":"选择题","link":"#选择题","children":[]},{"level":3,"title":"问答题","slug":"问答题","link":"#问答题","children":[]}],"relativePath":"Redis源码剖析与实战/期中测试-这些Redis源码知识，你都掌握了吗？.md","filePath":"Redis源码剖析与实战/期中测试-这些Redis源码知识，你都掌握了吗？.md","lastUpdated":1779816274000}'),n={name:"Redis源码剖析与实战/期中测试-这些Redis源码知识，你都掌握了吗？.md"};function l(r,e,d,o,p,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="期中测试-这些redis源码知识-你都掌握了吗" tabindex="-1">期中测试 | 这些Redis源码知识，你都掌握了吗？ <a class="header-anchor" href="#期中测试-这些redis源码知识-你都掌握了吗" aria-label="Permalink to &quot;期中测试 | 这些Redis源码知识，你都掌握了吗？&quot;">​</a></h1><p>你好，我是蒋德钧。</p><p>时间过得真快，从7月26日上线到现在，我们已经走过了一个半月的学习之旅，不知道你的收获如何呢？</p><p>前面我其实也说过，阅读和学习Redis源码确实是一个比较烧脑的任务，需要你多花些时间钻研。而从我的经验来看，阶段性的验证和总结是非常重要的。所以在这里，我特别设置了期中考试周，从9月13日开始到9月19日结束，这期间我们会暂停更新正文内容，你可以好好利用这一周的时间，去回顾一下前20讲的知识，做一个巩固。</p><p>有标准才有追求，有追求才有动力，有动力才有进步。一起来挑战一下吧，开启你的期中考试之旅。</p><p>我给你出了一套测试题，包括一套选择题和一套问答题。</p><ul><li>选择题：满分共 100 分，包含4道单选题和6道多选题。提交试卷之后，系统会自动评分。</li><li>问答题：包括2道题目，不计入分数，但我希望你能认真回答这些问题，可以把你的答案写在留言区。在9月16日这一天，我会公布答案。</li></ul><h3 id="选择题" tabindex="-1">选择题 <a class="header-anchor" href="#选择题" aria-label="Permalink to &quot;选择题&quot;">​</a></h3><p><a href="http://time.geekbang.org/quiz/intro?act_id=926&amp;exam_id=2699" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Redis%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/417936/28d1be62669b4f3cc01c36466bf811a4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Redis%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/417936/28d1be62669b4f3cc01c36466bf811a4.png" alt=""></a></a></p><h3 id="问答题" tabindex="-1">问答题 <a class="header-anchor" href="#问答题" aria-label="Permalink to &quot;问答题&quot;">​</a></h3><p><strong>第一题</strong></p><p>Redis源码中实现的哈希表在rehash时，会调用dictRehash函数。dictRehash函数的原型如下，它的参数n表示本次rehash要搬移n个哈希桶（bucket）中的数据。假设dictRehash被调用，并且n的传入值为10。但是，在dictRehash查找的10个bucket中，前5个bucket有数据，而后5个bucket没有数据，那么，本次调用dictRehash是否就只搬移了前5个bucket中的数据？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int dictRehash(dict *d, int n)</span></span></code></pre></div><p><strong>第二题</strong></p><p>Redis的事件驱动框架是基于操作系统IO多路复用机制进行了封装，以Linux的epoll机制为例，该机制调用epoll_create函数创建epoll实例，再调用epoll_ctl将监听的套接字加入监听列表，最后调用epoll_wait获取就绪的套接字再进行处理。请简述Redis事件驱动框架中哪些函数和epoll机制各主要函数有对应的调用关系。</p><p>好了，这节课就到这里。希望你能抓住期中周的机会，查漏补缺，快速提升Redis源码的阅读和学习能力。我们下节课再见！</p>',16)])])}const u=t(n,[["render",l]]);export{_ as __pageData,u as default};
